<template>
  <div class="layout-px-spacing">
    <ul class="navbar-nav flex-row mt-2">
      <li>
        <div class="page-header">
          <nav class="breadcrumb-one" aria-label="breadcrumb">
            <ol class="breadcrumb">
              <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
              <li class="breadcrumb-item active" aria-current="page">
                <span>Goods Issue Note</span>
              </li>
            </ol>
          </nav>
        </div>
      </li>
    </ul>

    <div v-if="loading_spinner" v-html="tableShimmer()"></div>

    <div v-else-if="!issue" class="text-center text-muted my-5">
      Good Issue Note not found.
    </div>

    <template v-else>
      <div class="d-flex justify-content-between align-items-center mb-3">
        <h4 class="text-center flex-grow-1">GOODS ISSUE NOTE</h4>
        <button class="btn btn-success me-2" @click="printIssueNote()">
          <i class="bi bi-printer fs-5"></i>
        </button>
      </div>

      <form @submit.prevent="submitDeliveryNote()">
        <div class="row layout-top-spacing">
          <div class="panel p-0">
            <div class="my-4 custom-table table3 table-responsive">
              <table class="table table-hover table-striped table-bordered">
                <tbody>
                  <tr>
                    <td><strong>Source:</strong></td>
                    <td>{{ issue.from }}</td>
                    <td><strong>Destination:</strong></td>
                    <td>{{ issue.to }}</td>
                  </tr>
                  <tr>
                    <td><strong>Status:</strong></td>
                    <td>
                      <span class="badge" :class="`badge-${issue.status?.color}`">
                        {{ issue.status?.name }}
                      </span>
                    </td>
                    <td><strong>Requester:</strong></td>
                    <td>{{ issue.requester }}</td>
                  </tr>
                  <tr>
                    <td><strong>Issuer:</strong></td>
                    <td>{{ issue.issuer }}</td>
                    <td><strong>Receiver:</strong></td>
                    <td>{{ issue.receiver }}</td>
                  </tr>
                  <tr>
                    <td><strong>Received date:</strong></td>
                    <td colspan="3">{{ issue.received_date }}</td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        </div>

        <div
          v-if="(issue.status?.id == 9 || issue.status?.id == 28) && user_permissions.includes('can_issue_goods')"
          class="d-flex flex-wrap gap-3 align-items-end mb-4"
        >
          <div style="min-width: 280px;">
            <label class="form-label small mb-2">Purpose</label>
            <Multiselect
              v-model="purpose"
              :options="purposes"
              placeholder="Select Purpose"
              :searchable="true"
              label="name"
              :multiple="false"
              :allow-empty="false"
              class="w-100"
            />
          </div>

          <div v-if="purpose && issue.status?.id != 28" style="min-width: 280px;">
            <label class="form-label small mb-2">Destination Store</label>
            <Multiselect
              v-model="store"
              :options="stores"
              placeholder="Select A Store"
              :searchable="true"
              label="name"
              :multiple="false"
              :allow-empty="true"
              class="w-100"
            />
          </div>
        </div>

        <div class="row">
          <div :class="issue.status?.id == 28 ? 'col-md-8' : 'col-md-12'">
            <table
              v-if="issue.status?.id == 9 || issue.status?.id == 28"
              class="table table-bordered table-striped mb-0 w-100"
              style="table-layout: fixed;"
            >
              <thead class="table-light">
                <tr>
                  <th style="min-width: 150px;">Item Requested</th>
                  <th class="text-center" style="min-width: 80px;">Unit</th>
                  <th class="text-center" style="min-width: 150px;">Item Issued</th>
                  <th class="text-center" style="min-width: 120px;">Qty Requested</th>
                  <th class="text-center" style="min-width: 320px; width: 40%;">Qty Delivered</th>
                </tr>
              </thead>
              <tbody>
                <tr v-for="(item, idx) in issuedItems" :key="idx">
                  <td>{{ item.item_requested }}</td>
                  <td class="text-center">{{ item.unit }}</td>
                  <td class="text-center">{{ item.quantity_requested }}</td>
                  <td class="text-center">{{ item.quantity_issued }}</td>
                  <td v-if="(store || issue.status?.id == 28) && user_permissions.includes('can_issue_goods')">
                    <div class="d-flex gap-2 flex-wrap">
                      <div style="flex: 1; min-width: 200px;">
                        <Multiselect
                          v-if="issue.status?.id == 28"
                          v-model="item.convertibles"
                          :options="storeItems"
                          placeholder="Select Item"
                          track-by="id"
                          :searchable="true"
                          label="name"
                          :multiple="true"
                          :allow-empty="true"
                          class="w-100"
                        />
                      </div>
                      <div v-if="issue.status?.id != 28" style="min-width: 120px; width: 100%; margin-top: 0.5rem;">
                        <input
                          type="number"
                          class="form-control"
                          placeholder="Qty"
                          v-model.number="item.received"
                          required
                          style="width: 100%;"
                        />
                      </div>
                    </div>
                  </td>
                  <td v-else class="text-end">{{ item.received }}</td>
                </tr>
              </tbody>
            </table>

            <v-client-table
              v-else
              :data="issuedItems"
              :columns="issuedItemColumns"
              :options="table_option"
              style="width: 100%;"
            />
          </div>

          <div class="col-md-4" v-if="issue.status?.id == 28">
            <table class="table">
              <thead>
                <tr>
                  <th scope="col">#</th>
                  <th scope="col">Item</th>
                  <th scope="col">Quantity</th>
                </tr>
              </thead>
              <tbody>
                <tr v-for="(item, index) in allConvertibles" :key="item.id">
                  <th scope="row">{{ index + 1 }}</th>
                  <td>{{ item.name }}<br /><sub>{{ item.condition }}</sub></td>
                  <td>
                    <input
                      type="number"
                      step="any"
                      placeholder="Enter Quantity"
                      v-model="item.quantity"
                      class="form-control"
                    />
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>

        <div class="text-end mt-3">
          <button
            v-if="(issue.status?.id == 9 || issue.status?.id == 28) && user_permissions.includes('can_fill_delivery_note')"
            type="submit"
            class="btn btn-success"
            :disabled="(!store && issue.status?.id != 28) || loading"
          >
            <span v-if="loading" v-html="loadingSpinner()"></span>
            <span v-else>Save</span>
          </button>
        </div>
      </form>
    </template>
  </div>
</template>

<script setup>
import { ref, inject, computed, onMounted } from "vue";
import { useRoute, useRouter } from "vue-router";
import axios from "axios";
import { useMeta } from "@/composables/use-meta";
import Multiselect from "@suadelabs/vue3-multiselect";
import "@suadelabs/vue3-multiselect/dist/vue3-multiselect.css";

useMeta({ title: "Goods Issue Note" });

const route = useRoute();
const router = useRouter();

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL,
});

const showMessage = inject("showMessage");
const showError = inject("showError");
const tableShimmer = inject("tableShimmer");
const loadingSpinner = inject("loadingSpinner");
const formatDate = inject("formatDate");

const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
const user_id = JSON.parse(localStorage.getItem("user")).id;

const loading_spinner = ref(false);
const loading = ref(false);
const issue = ref(null);
const issuedItems = ref([]);
const issuedItemColumns = ref([
  "Sno", "item_requested", "category", "unit",
  "item_issued", "quantity_requested", "quantity_issued", "received",
]);

const purpose = ref({ id: 1, name: "Warehouse Storage" });
const purposes = ref([{ id: 1, name: "Warehouse Storage" }]);

const store = ref("");
const stores = ref([]);
const storeItems = ref([]);

const table_option = ref({
  perPage: 20,
  perPageValues: [20, 50, 100],
  skin: "table table-hover table-striped",
  columnsClasses: { actions: "actions text-center" },
  sortable: ["SNo"],
  sortIcon: { base: "sort-icon-none", up: "sort-icon-asc", down: "sort-icon-desc" },
  pagination: { nav: "scroll", chunk: 5 },
  texts: {
    count: "Showing {from} to {to} of {count}",
    filter: "",
    filterPlaceholder: "Search...",
    limit: "Results:",
  },
  resizableColumns: false,
});

const allConvertibles = computed(() =>
  issuedItems.value.flatMap((item) => item.convertibles ?? [])
);

const mapIssue = (item) => ({
  ...item,
  id: item.id,
  from: (item.source_store?.project?.short_name ?? "") + " - " + (item.source_store?.name ?? ""),
  to: ["TRANSFER", "CONVERSION"].includes(item.purpose)
    ? `${item?.destination_store?.project?.short_name || ""} - ${item?.destination_store?.name || "DIRECT CONSUMPTION"}`
        .trim()
        .replace(/^-\s*|\s*-\s*$/g, "")
    : "DIRECT CONSUMPTION",
  issuer: item?.issuer?.name,
  requester: item?.requisition?.requester?.name ?? "---",
  receiver: item?.good_delivery_note?.receiver?.name ?? "---",
  received_date: formatDate(item?.good_delivery_note?.created_at) ?? "---",
  source_store_id: item.source_store_id,
  destination_store_id: item.destination_store_id || "Direct Consumption",
  date_issued: formatDate(item.created_at),
});


const gin = ref('');
const getIssueNote = async () => {
  loading_spinner.value = true;
  try {
    const { data } = await axiosInstance.get(`good-issue-notes?gin_id=${gin.value}`);
    const record = data?.[0];

    if (!record) {
      issue.value = null;
      return;
    }

    issue.value = mapIssue(record);

    if (record.status_id == 28) {
      await getStoreItems(record.source_store_id);
    }

    if (record.destination_store) {
      store.value = {
        id: record.destination_store?.id,
        name: record.destination_store
          ? (record.destination_store.project?.short_name) + " - " + (record.destination_store.name)
          : "",
      };
    }

    issuedItems.value = record.items.map((d, index) => {
      const delivered = d.delivered_items || {};
      return {
        ...d,
        Sno: index + 1,
        item_requested: d.requisition_item.remark,
        category: d.store_item.item.category?.name,
        item_issued: d.store_item.item.name,
        quantity_requested: d.requisition_item.quantity,
        quantity_issued: d.quantity,
        received: delivered.quantity ?? "",
        unit: d.requisition_item.units ?? delivered.unit ?? "---",
        convertibles: [],
      };
    });
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    loading_spinner.value = false;
  }
};
const getStoreItems = async (id) => {
  const response = await axiosInstance.get(`get-store-items?store_id=${id}`);
  storeItems.value = response.data;
};

const submitDeliveryNote = async () => {
  loading.value = true;
  const payload = {
    deliveryData: {
      purpose: issue.value.purpose,
      gin_id: issue.value.id,
      receiver_id: user_id,
    },
    convertibleItems: issuedItems.value.flatMap((item) => item.convertibles ?? []),
    deliveryItems: issuedItems.value.map((item) => ({
      gin_item_id: item.id,
      item_id: item.store_item.item_id,
      store_item_id: item.store_item.id,
      item_condition: item.store_item.item_condition ?? item.store_item.condition,
      quantity: item.received,
      purpose: purpose.value.id,
      store_id: store.value.id,
      unit: item.unit.short_name ?? item.store_item.unit,
    })),
  };

  try {
    await axiosInstance.post("good-delivery-notes", payload);
    showMessage("Data Saved Successfully");
    issue.value.status = { id: 10, name: "Delivered", color: "success" };
    router.back();
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    loading.value = false;
  }
};

const printIssueNote = async () => {
  try {
    const iframe = document.createElement("iframe");
    iframe.style.display = "none";
    document.body.appendChild(iframe);

    const sourceStore = issue.value.source_store ? `${issue.value.source_store.project?.short_name || ''} - ${issue.value.source_store.name || ''}` : 'N/A';
    const destinationStore = issue.value.destination_store ? `${issue.value.destination_store.project?.short_name || ''} - ${issue.value.destination_store.name || ''}` : 'DIRECT CONSUMPTION';

    const printContent = `
<!DOCTYPE html>
<html>
<head>
<title>Good Issue Note</title>
<style>
  body { font-family: 'Courier New', monospace; margin: 40px; font-size: 13px; }
  .text-style { font-family: 'Courier New', monospace; }
  .company-title { text-align: center; }
  .title { text-align: center; font-size: 20px; margin: 10px 0; }
  .info-section { margin: 20px 0; }
  .info-row { display: flex; justify-content: space-between; margin: 5px 0; }
  table { width: 100%; border-collapse: collapse; margin-top: 10px; font-size: 12px; }
  th, td { border: 0.5px solid #000; padding: 6px; }
  th { background-color: #f8f8f8; font-weight: bold; }
  .text-right { text-align: right; }
  .text-center { text-align: center; }
  hr { border: 0; border-top: 0.5px solid #000; margin: 0px 0; }
  @media print { body { margin: 10mm; } }
</style>
</head>
<body>
  <div style="font-size:18px">
ISSUE NOTE NO:
<span style="color:red">0${issue.value.id}/${new Date(issue.value.created_at).getFullYear().toString().slice(-2)}</span>
</div>

<div class="company-title text-style">
  <i>
  <h1>COPEX CONTRACTORS CO.LTD</h1>
  <div><b>Address:</b> Msamvu, P.O.BOX 678, Morogoro</div>
  <div><b>Tel:</b> 0713 000 777, 0657 111 555</div>
  <div><b>Email:</b> info@copexcontractors.co.tz</div>
  <div><b>TIN:</b> 135-489-247 &nbsp;&nbsp; <b>VRN:</b> 40-032826C</div>
  </i>
</div>

<hr style="margin-top:20px">

<div class="title text-style">
  GOOD ISSUE NOTE
</div>

<hr>

<div class="info-section">
  <div class="info-row">
    <div><strong>Requisition No:</strong> ${issue.value.requisition_id || 'N/A'}</div>
    <div><strong>Issue Note No:</strong>0${issue.value.id || 'N/A'}</div>
  </div>
  <div class="info-row">
    <div><strong>Date:</strong>0${issue.value.date_issued || 'N/A'}</div>
    <div><strong>Status:</strong> ${issue.value.status?.name || 'N/A'}</div>
  </div>
  <div class="info-row">
    <div><strong>From:</strong> ${sourceStore}</div>
    <div><strong>To:</strong> ${destinationStore}</div>
  </div>

    <div class="info-row">
    <div><strong>Issuer :</strong> ${issue.value.issuer || 'N/A'}</div>
    <div><strong>Receiver:</strong> ${issue.value.good_delivery_note?.receiver.name}</div>
  </div>


</div>

<table>
  <thead>
    <tr>
      <th>SN</th>
      <th>Item Requested</th>
      <th>Category</th>
      <th>Unit</th>
      <th>Item Issued</th>
      <th class="text-right">Qty Requested</th>
      <th class="text-right">Qty Issued</th>
    </tr>
  </thead>
  <tbody>
    ${issuedItems.value.map((item, index) => `
    <tr>
      <td>${index + 1}</td>
      <td>${item.item_requested || 'N/A'}</td>
      <td>${item.category || 'N/A'}</td>
      <td>${item.unit || 'N/A'}</td>
      <td>${item.item_issued || 'N/A'}</td>
      <td class="text-right">${item.quantity_requested || '0'}</td>
      <td class="text-right">${ (item.quantity_issued).toFixed(2) || '0'}</td>
    </tr>
    `).join('')}
  </tbody>
</table>


<div style="display: flex; justify-content: flex-start; margin-top: 30px; font-size: 13px; gap: 80px;">
  <div>
    <strong> Requester:</strong> <span style="border-bottom: 1px solid #000; display: inline-block; min-width: 80px;" class="text-center">${issue.value.requester || 'N/A'}</span>
  </div>
  <div>
    <strong>Issuer:</strong> <span style="border-bottom: 1px solid #000; display: inline-block; min-width: 80px;" class="text-center">${issue.value.issuer || 'N/A'}</span>
  </div>
    <div>
    <strong>Receiver :</strong> <span style="border-bottom: 1px solid #000; display: inline-block; min-width: 80px;" class="text-center">${issue.value.good_delivery_note?.receiver.name|| 'N/A'}</span>
  </div>

</div>



</body>
</html>
`;

    const iframeDoc = iframe.contentWindow.document;
    iframeDoc.open();
    iframeDoc.write(printContent);
    iframeDoc.close();

    iframe.onload = () => {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();
      setTimeout(() => {
        document.body.removeChild(iframe);
      }, 1000);
    };
  } catch (error) {
    showError(`Failed to print issue note: ${error.message}`);
  }
};

onMounted(getIssueNote);
</script>